A = list(range(0,7))    # size 7
B = list(range(7,14))   # size 7
C = list(range(14,20))  # size 6

edges = []
for a in A:
    for b in B: edges.append((a,b))
for a in A:
    for c in C: edges.append((a,c))
for b in B:
    for c in C: edges.append((b,c))

# Verify
from itertools import combinations
V = range(20)
adj = {v:set() for v in V}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

# min degree
print("min deg:", min(len(adj[v]) for v in V))

# check no K4
def hasK4():
    for quad in combinations(V,4):
        if all(b in adj[a] for a,b in combinations(quad,2)):
            return True
    return False
print("has K4:", hasK4())

# 3-color check
color = {}
for v in A: color[v]=0
for v in B: color[v]=1
for v in C: color[v]=2
print("proper 3-coloring:", all(color[u]!=color[v] for u,v in edges))

print("num edges:", len(edges))
print(edges)
